import { usingFixtureAdmin } from '../support/commands';

/**
 * Generated by Cypress Author, 2026-09-10.
 *
 * Admin Notifications (`/notifications`): three defects fixed together in
 * PR #731, from the same walk that also produced the Settings issues covered
 * by `settings.cy.ts`.
 *
 * - #705: the card body (title, summary, description) is the disclosure
 *   control, not only the title text. Clicking the summary line an operator
 *   naturally clicks now expands the card.
 * - #706: Approve/Deny is offered only on a fresh, undecided booking request
 *   (`kincare.requested`), never on a booking notification that has already
 *   been acted on (e.g. a confirmation).
 * - #707: a read row is visibly dimmed, not just relabelled. `notif-row--read`
 *   is the class the screen's own CSS keys the dimming off (screens.css), so
 *   that is what this file asserts rather than a computed color.
 *
 * SEEDED FIXTURES, NOT THE SHARED SEED. The shared seed (`e2e/seed.rows.ts`)
 * writes three `notifications` docs for the visual/Playwright suite, and one
 * of them (`vis-note-3`, "KinTale delivered") already carries a `readAt`, so
 * the read-row half of #707 needs nothing extra. Neither #705 (a resolved
 * `detail` block, so the card has something to disclose) nor #706's positive
 * case (`kincare.requested` against a real booking target) exists in that
 * seed, so this file writes its own two rows through the `upsertDoc` Cypress
 * task (`cypress.config.ts`, backed by `e2e/seed.ts`'s `upsert`) and removes
 * them again in `after`, so a later run of this spec (or another spec file
 * later in the same `cypress open` session) sees the shared seed unchanged.
 *
 * ADDRESSED TO THE FIXTURE ADMIN (#1837). The screen lists only the signed-in
 * staff member's own notices (`recipientUid == uid`), so both rows are written
 * with `adminUidFields: ['recipientUid']`, and the last test seeds one row
 * addressed to a household to prove it stays off this screen.
 *
 * UI-ONLY, per the 2026-09-01 operator ruling. Reading the feed is a live
 * Firestore listener (`notificationsQueryFor`), and expanding a card and
 * reading a row's own class are pure client state and CSS. One callable is
 * stubbed with `cy.intercept` (fine for callables, same ruling):
 * `listPendingBookingRequests`, because since #2069 a request row offers
 * Approve and Deny only when the live queue of waiting requests holds it.
 */

const CALLABLE = (name: string) => `**/us-central1/${name}`;

/** #2069: the waiting queue, holding [requests]. */
function stubWaitingRequests(requests: readonly unknown[]) {
  cy.intercept('POST', CALLABLE('listPendingBookingRequests'), {
    statusCode: 200,
    body: { result: { requests } },
  }).as('listPending');
}

/** The request PENDING_DOC is about, as the Bookings queue lists it. */
const WAITING_REQUEST = {
  kinfolkId: 'e2e-kf-1',
  batchId: 'e2e-notif-visit-1',
  kinfolkName: 'Wanda Thorne',
  serviceType: 'Dog walking',
  kinNames: ['Biscuit'],
  notes: null,
  visitCount: 1,
  firstStartTimeMs: Date.now() + 3 * 86_400_000,
  lastStartTimeMs: Date.now() + 3 * 86_400_000,
  startTimeMsList: [Date.now() + 3 * 86_400_000],
  visits: [],
  requestedAtMs: Date.now(),
};

const PENDING_ID = 'e2e-notif-pending';
const CONFIRMED_ID = 'e2e-notif-confirmed';

/** A fresh, undecided KinCare request: #705's disclosure target, #706's positive case. */
const PENDING_DOC = {
  key: 'kincare.requested',
  category: 'booking',
  title: 'KinCare visit requested',
  description: 'A new KinCare visit request came in.',
  actorName: 'Wanda Thorne',
  targetType: 'booking',
  targetId: 'e2e-notif-visit-1',
  data: { kinfolkId: 'e2e-kf-1' },
  // Resolved server-side detail, exactly as `buildNotificationDetail.ts` would
  // stamp it: this is what makes the card openable (`hasNotificationDetail`)
  // and gives it a collapsed summary line to click.
  detail: {
    requestedBy: 'Wanda Thorne',
    kinfolkName: 'Wanda Thorne',
    kinName: 'Biscuit',
    serviceType: 'Dog walking',
    bookingDate: 'Sep 12',
    bookingTime: '3:00 PM',
  },
  // A `cy.task` argument crosses as JSON, so this arrives at the task as a
  // plain string; `timestampFields` below (see cypress.config.ts) turns it
  // back into a real Timestamp before it is written, which is what
  // `lib/time.ts`'s `tsToDate` (and therefore the whole row) needs.
  createdAt: new Date().toISOString(),
};

/** A booking notification that is NOT a pending request: #706's negative case. */
const CONFIRMED_DOC = {
  key: 'kincare.booking.confirm',
  category: 'booking',
  title: 'KinCare booking confirmed',
  description: 'The visit is on the calendar.',
  actorName: 'Auntie',
  targetType: 'booking',
  targetId: 'e2e-notif-visit-2',
  data: { kinfolkId: 'e2e-kf-1' },
  createdAt: new Date(Date.now() - 60_000).toISOString(),
};

/**
 * #1837: a notice addressed to a household, not to the admin. It must never be
 * drawn on the admin's Notifications screen. `recipientUid` is a household
 * account's uid, deliberately not the fixture admin's.
 */
const HOUSEHOLD_ID = 'e2e-notif-household';
const HOUSEHOLD_DOC = {
  key: 'kincare.auntie.arrived',
  category: 'booking',
  recipientUid: 'e2e-household-account',
  title: 'Your Auntie has arrived',
  description: 'Addressed to the household.',
  actorName: 'Auntie',
  targetType: 'booking',
  targetId: 'e2e-notif-visit-1',
  data: { kinfolkId: 'e2e-kf-1' },
  createdAt: new Date(Date.now() - 30_000).toISOString(),
};
describe('notifications', () => {
  // One `before`, not two: `usingFixtureAdmin()` is read synchronously and
  // `this.skip()` on a deployed-host run must stop the seeding hook too
  // (`upsert` hardcodes the emulator's own 127.0.0.1 ports), so the skip and
  // the seed cannot be separate hooks the deployed-host run might partially
  // run.
  before(function () {
    if (!usingFixtureAdmin()) this.skip();
    cy.task('upsertDoc', {
      collection: 'notifications',
      id: PENDING_ID,
      doc: PENDING_DOC,
      timestampFields: ['createdAt'],
      adminUidFields: ['recipientUid'],
    });
    cy.task('upsertDoc', {
      collection: 'notifications',
      id: CONFIRMED_ID,
      doc: CONFIRMED_DOC,
      timestampFields: ['createdAt'],
      adminUidFields: ['recipientUid'],
    });
    cy.task('upsertDoc', {
      collection: 'notifications',
      id: HOUSEHOLD_ID,
      doc: HOUSEHOLD_DOC,
      timestampFields: ['createdAt'],
    });
  });

  after(function () {
    if (!usingFixtureAdmin()) return;
    cy.task('deleteDoc', { collection: 'notifications', id: PENDING_ID });
    cy.task('deleteDoc', { collection: 'notifications', id: CONFIRMED_ID });
    cy.task('deleteDoc', { collection: 'notifications', id: HOUSEHOLD_ID });
  });

  // The support file's global afterEach reads and asserts on `console.error`
  // for every test in every spec; nothing extra is needed here.

  it("#705 clicking a notification card's summary line expands its detail (aria-expanded flips)", () => {
    cy.signIn();
    cy.visit('/notifications');

    cy.contains('.notif-row', 'KinCare visit requested').within(() => {
      cy.get('.notif-row__key--button').should('have.attr', 'aria-expanded', 'false');
      cy.get('.notif-row__detail').should('not.exist');
      // The collapsed summary line, not the title: issue #705 was that only
      // the title text opened the card, and the summary is where the
      // operator's cursor actually was in the walk.
      cy.get('.notif-row__summary').should('contain.text', 'Biscuit').click();
      cy.get('.notif-row__key--button').should('have.attr', 'aria-expanded', 'true');
      cy.get('.notif-row__detail')
        .should('exist')
        .and('contain.text', 'Wanda Thorne')
        .and('contain.text', 'Dog walking');
    });
  });

  it('#706 offers Approve and Deny only on a pending KinCare request, never on a confirmed booking', () => {
    stubWaitingRequests([WAITING_REQUEST]);
    cy.signIn();
    cy.visit('/notifications');

    cy.contains('.notif-row', 'KinCare visit requested').within(() => {
      cy.contains('button', 'Approve').should('exist');
      cy.contains('button', 'Deny').should('exist');
    });
    cy.contains('.notif-row', 'KinCare booking confirmed').within(() => {
      cy.contains('button', 'Approve').should('not.exist');
      cy.contains('button', 'Deny').should('not.exist');
    });
  });

  it('#2069 a request the waiting queue no longer holds offers Open only', () => {
    stubWaitingRequests([]);
    cy.signIn();
    cy.visit('/notifications');
    cy.wait('@listPending');
    cy.contains('.notif-row', 'KinCare visit requested').within(() => {
      cy.contains('button', 'Approve').should('not.exist');
      cy.contains('button', 'Deny').should('not.exist');
      cy.contains('button', 'Open').should('exist');
      cy.contains('Answered').should('exist');
    });
  });

  it('#1875 Deny asks first, naming the household, and sends nothing on Cancel', () => {
    stubWaitingRequests([WAITING_REQUEST]);
    cy.intercept('POST', CALLABLE('manageBookingSeries'), cy.spy().as('answer'));
    cy.signIn();
    cy.visit('/notifications');
    cy.contains('.notif-row', 'KinCare visit requested').within(() => {
      cy.contains('button', 'Deny').click();
    });
    cy.get('[role="dialog"]').within(() => {
      cy.contains('Turn down this request from Wanda Thorne').should('exist');
      cy.contains('The household will be told.').should('exist');
      cy.contains('button', 'Cancel').click();
    });
    cy.get('[role="dialog"]').should('not.exist');
    cy.get('@answer').should('not.have.been.called');
  });

  it('#2028 Open on a waiting request opens its card on Bookings, not "Booking unavailable"', () => {
    stubWaitingRequests([WAITING_REQUEST]);
    cy.intercept('POST', CALLABLE('listRescheduleRequests'), { statusCode: 200, body: { result: { requests: [] } } });
    cy.intercept('POST', CALLABLE('listCancelRequests'), { statusCode: 200, body: { result: { requests: [] } } });
    cy.signIn();
    cy.visit('/notifications');
    cy.contains('.notif-row', 'KinCare visit requested').within(() => {
      cy.contains('button', 'Open').click();
    });
    cy.location('pathname').should('eq', '/bookings');
    cy.get('[role="dialog"]').should('contain.text', 'New request from Wanda Thorne');
    cy.contains('Booking unavailable').should('not.exist');
  });

  it('#707 a read row is dimmed and offers Mark unread; an unread row is not and offers Mark read', () => {
    cy.signIn();
    cy.visit('/notifications');

    // `vis-note-3` from the shared seed: already read (`readAt` stamped at
    // seed time), so this is the state as an operator lands on it, not a
    // state this test produces by clicking Mark read.
    cy.contains('.notif-row', 'KinTale delivered')
      .should('have.class', 'notif-row--read')
      .and('not.have.class', 'notif-row--unread')
      .within(() => {
        cy.contains('button', 'Mark unread').should('exist');
        cy.contains('button', 'Mark read').should('not.exist');
      });

    cy.contains('.notif-row', 'KinCare visit requested')
      .should('have.class', 'notif-row--unread')
      .and('not.have.class', 'notif-row--read')
      .within(() => {
        cy.contains('button', 'Mark read').should('exist');
        cy.contains('button', 'Mark unread').should('not.exist');
      });
  });

  it('#1837 lists the notices addressed to the signed-in admin and none addressed to a household', () => {
    cy.signIn();
    cy.visit('/notifications');
    // The admin's own rows are drawn, so the absence below is not an empty or
    // still-loading list.
    cy.contains('.notif-row', 'KinCare visit requested').should('exist');
    cy.contains('.notif-row', 'KinCare booking confirmed').should('exist');
    cy.contains('.notif-row', 'Your Auntie has arrived').should('not.exist');
    cy.contains('Addressed to the household.').should('not.exist');
  });
});
